// Generated by InfraKit Visual Editor.
// require() and wiring order below follows the arrows you drew on the
// canvas (topologically sorted). Nodes with no incoming edge run first.
// Each package's wiring call matches its real exported API. "core" is only
// required at all when the dashboard is enabled (the only package in this
// catalog with a hard runtime dependency on it).
const express = require("express");
const config = require("./infrakit.config.js");

const core = require("@infrakit/core");
const { applyRateLimits } = require("@infrakit/rate-limiter");
const shield = require("@infrakit/shield");
const logger = require("@infrakit/logger");
const cache = require("@infrakit/cache");
const loadbalancer = require("smart-stick-loadbalancer");
const fn = require("@infrakit/fn");
const breaker = require("@infrakit/breaker");
const queue = require("@infrakit/queue");
const health = require("@infrakit/health");
const dashboard = require("@infrakit/dashboard");

const app = express();

// --- rate-limiter ---
applyRateLimits(app, (config.rateLimiter || {}).routes || {});
// --- shield ---
shield.init(app, config.shield || {});
// --- logger ---
logger.init(app, config.logger || {});
// --- cache (2 instances — see NOTE in infrakit.config.js) ---
// instance: Product Cache
cache.init(config.cache["Product Cache"] || {});
// cache has no middleware to mount — call its API where you need it (e.g. app.get("/path", cache.route(60000), handler)).
// instance: Session Cache
cache.init(config.cache["Session Cache"] || {});
// cache has no middleware to mount — call its API where you need it (e.g. app.get("/path", cache.route(60000), handler)).
// --- fn (2 instances — see NOTE in infrakit.config.js) ---
// instance: Order Service
fn.init(app, config.fn["Order Service"] || {});
// instance: Product Service
fn.init(app, config.fn["Product Service"] || {});
// --- breaker ---
breaker.init(config.breaker || {});
// breaker has no middleware to mount — call its API where you need it (e.g. await breaker.execute("service-name", async () => { ... })).
// --- queue ---
queue.init(config.queue || {});
// queue has no middleware to mount — call its API where you need it (e.g. queue.process("name", handler) / queue.add("name", payload)).
// --- health ---
health.init(config.health || {});
app.use(health.middleware());
// --- dashboard access (continuous revocation check) ---
// Mounted BEFORE dashboard.init() so it gates every dashboard route,
// not just /login — this is what lets the platform revoke access later.
app.use("/infrakit", require("./infrakit-dashboard-auth-check.js"));
// --- dashboard ---
dashboard.init(app, config.dashboard || {});
// --- dashboard access (project key + password login) ---
// Factory function, not a plain router — it needs the same "app" instance
// to relay a real login into dashboard. See that file's header for why.
app.use("/infrakit-access", require("./infrakit-dashboard-login.js")(app));

module.exports = app;


